negativeExample:
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

// This example should NOT match if project source version is below 16.
// For illustration, imagine a project configured for Java 11.
public class NegativeExample {
    public List<String> legacyMethod(String[] items) {
        // Stream.toList() is not available in Java 11.
        return Arrays.stream(items).collect(Collectors.toList());
    }

    public List<String> otherCollector(String[] items) {
        // Should not match other collectors
        return Arrays.stream(items).collect(Collectors.toSet());
    }

    public List<String> otherMethodCall(String[] items) {
        // Should not match other method calls on stream
        return Arrays.stream(items).distinct().collect(Collectors.toList());
    }
}
